head.script:
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp = js_market;
scwin.gAcptNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM); // 법인코드 및 법인명(회사명) 관련
        Grd_com_isur.style.zIndex = 30;
        await scwin.setCode(); // 공시일자(from~to)
        scwin.init(); // 시장구분
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16514.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    txb_TotalCnt.hide(); // 총건수

    if (scwin.gLdMktTp !== '2') {
        scwin.gLdMktTp = '1';
    }
    rdo_MKT_ID.setValue(scwin.gLdMktTp);

    // 콘트롤 잠그기
    rdo_MKT_ID.setDisabled(true);
    rdo_MKT_ID.setValue(scwin.gLdMktTp);
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2') {
        panel_mkt.hide();
    }
    if (scwin.gLdMktTp === '1') {
        cmb_EduApctTpCd.CBData = "^--,11^[유가]공시책임자,12^[유가]공시담당자";
    } else if (scwin.gLdMktTp === '2') {
        cmb_EduApctTpCd.CBData = "^--,1^[코스닥]공시책임자,2^[코스닥]공시담당자";
    } else {
        cmb_EduApctTpCd.CBData = "^--,11^[유가]공시책임자,12^[유가]공시담당자,1^[코스닥]공시책임자,2^[코스닥]공시담당자";
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE); // 공시일자-종료일 이미지 버튼 클릭 시 달력 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.btn_SDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_EDATE_onclick
 * @description btn_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDATE_onclick = function() {
    try {
        popUpCalendar2(edt_EDATE); // 공시일자-시작일 이미지 버튼 클릭 시 달력 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.btn_EDATE_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        if (vTp === '0') {
            edt_SDATE.setValue('');
            edt_EDATE.setValue('');
        } else {
            $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE); // 기간선택 콤보박스

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM); // 법인명 검색 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name dts_dts_EduCrsNm_OnFilter
 * @description dts Edu Crs Nm On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_dts_EduCrsNm_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "" || scwin.gDepCd === "UPTEAM") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_emp.getCellData(row, "dep_cd") === "UPTEAM" ||
                dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.dts_dts_EduCrsNm_OnFilter" });
    }
};

/**
 * @method
 * @name cmb_EduApctTpCd_onselchange
 * @description cmb_EduApctTpCd onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_EduApctTpCd_onselchange = async function() {
    try {
        gubun = $c.cp.valueOfIndex(cmb_EduApctTpCd, "VALUE", cmb_EduApctTpCd.getSelectedIndex());
        // alert("gubun : " + gubun);
        if (gubun !== '') {
            await scwin.getDisclsEduRnd(gubun);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16514.cmb_EduApctTpCd_onselchange" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search(); // 조회 버튼
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16514.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotalCnt.setValue("총건수 : " + rowcount);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name file_OnClick
 * @description file 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.file_OnClick = function() {
    try {
        scwin.selectAttach();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.file_OnClick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「엑셀업로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.excelUpload();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16514.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Modify_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Modify_onclick = function() {
    try {
        scwin.save();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.btn_Modify_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16514.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        let msg = $c.stf.getMessageParam("MSG-A001", LastJob);
        await $c.win.alert(msg);
        dts_FileList.removeAll();
        dts_FileList.insertRow();
        txb_ATTACH_FILE_NM.setValue('');
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16514.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_gridSave_OnFail
 * @description grid Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_gridSave_OnFail = async function() {
    try {
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16514.trs_gridSave_OnFail" });
    }
};

/**
 * @method
 * @name trs_gridSave_OnSuccess
 * @description grid Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_gridSave_OnSuccess = async function() {
    try {
        let msg = $c.stf.getMessageParam("MSG-A001", "저장");
        await $c.win.alert(msg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16514.trs_gridSave_OnSuccess" });
    }
};

/**
 * @method
 * @name grd_Grid_onexit
 * @description grd_Grid onexit 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} olddata olddata
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_onexit = async function(row, colid, olddata) {
    try {
        if (colid === "DISCLS_EDU_APPL_AMT") {
            await scwin.checkNum(row, colid, olddata);
        }
        if (colid === "DISCLS_EDU_COST_DEPO_DD") {
            await scwin.checkDate(row, colid, olddata);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16514.grd_Grid_onexit" });
    }
};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    try {
        scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
        if (scwin.gDepCd === '' || scwin.gDepCd === 'UPTEAM') {
            cmb_EmpList.setValue('');
        }
        dts_emp.UseFilter = true;
        dts_emp.Filter();
        dts_emp.sort("DEP_CD", 0);
        // dts_emp.sort(); // W-Craft 주석처리
        if (scwin.gDepCd !== '' && scwin.gDepCd !== 'UPTEAM') {
            cmb_EmpList.trigger("onclick");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.cmb_TeamList_onselchange" });
    }
};

/**
 * @method
 * @name dts_dep_OnLoadCompleted
 * @description dts_dep 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    try {
        if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
            $c.stf.copyDataSet(dts_dep, dts_dep1);
            scwin.addDsclTeamAll(rowcount);
            cmb_TeamList.setValue('UPTEAM');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.dts_dep_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "" || scwin.gDepCd === "UPTEAM") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_emp.getCellData(row, "dep_cd") === "UPTEAM" ||
                dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16514.dts_emp_OnFilter" });
    }
};

/**
 * @method
 * @name cmb_update_onselchange
 * @description cmb_update onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_update_onselchange = async function() {
    try {
        await scwin.allUpdate();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16514.cmb_update_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 공시일자, 팀, 담당자 세팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    // dts_FileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_FileList.insertRow();
    // dts_Master.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_Master.insertRow();

    //  기간 from~ to  셋팅(공시일자)
    /**
    vCurDate = cGetToday("yyyymmdd");
    edt_SDATE.text = cGetMinusYear(vCurDate,1) ; 	// 1년전 날짜
    edt_EDATE.text =vCurDate;	// 현재날짜
    setObjectValue(cmb_PeriodTp, '1');
     */
    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getDisclsEduRnd
