        return;
    } else {
        const discls_edu_crs_nm = cmb_EduCrsNm.getValue();
        if (discls_edu_crs_nm === '') {
            await $c.win.alert("교육회차를 선택하여 주세요.");
            return;
        } else {
            url += "&DISCLS_EDU_APPL_SEQ=" + discls_edu_crs_nm;
            url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp; // 법인코드
