            url += "&EMP_NO=" + cmb_EmpList.getValue(); // 담당자
            url += "&DEP_CD=" + cmb_TeamList.getValue(); // 팀(부서코드)
            url += "&SCREN_ID=" + 'ULDSTF16514.xml';
            url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
            const sbmOptions = {
                id : "sbm_dts_Grid",
                action : "/DisclsEduaction.do",
                ref : "",
                target : "dts_Grid=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name addDsclTeamAll
 * @description 공시팀 전체 목록에 추가
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.addDsclTeamAll = function(rowcount) {
    dts_dep.setCellData(2, "VALUE", 'UPTEAM');
    dts_dep.setCellData(2, "TEXT", '공시팀 전체');
    dts_dep.setCellData(2, "DEP_CD", 'UPTEAM');
    dts_dep.setBroadcast(false);
    for (let i = 3; i <= rowcount; i++) {
        dts_dep.setCellData(i, "VALUE", dts_dep1.getCellData(i - 1, "VALUE"));
        dts_dep.setCellData(i, "TEXT", dts_dep1.getCellData(i - 1, "TEXT"));
        dts_dep.setCellData(i, "DEP_CD", dts_dep1.getCellData(i - 1, "DEP_CD"));
    }
    dts_dep.setBroadcast(true, true);
    dts_dep.insertRow();
    dts_dep.setCellData(rowcount + 1, "VALUE", dts_dep1.getCellData(rowcount, "VALUE"));
    dts_dep.setCellData(rowcount + 1, "TEXT", dts_dep1.getCellData(rowcount, "TEXT"));
    dts_dep.setCellData(rowcount + 1, "DEP_CD", dts_dep1.getCellData(rowcount, "DEP_CD"));
};

/**
 * @method
 * @name selectAttach
 * @description select Attach 처리
 * @returns {void}
 * @hidden N
 */
scwin.selectAttach = function() {
    if (file.getValue() === "") return;
    txb_ATTACH_FILE_NM.setValue(file.getValue());
    dts_FileList.setCellData(1, "fileInfo", file.getValue());
    dts_FileList.setCellData(1, "fileUrl", file.getValue());
    dts_FileList.setCellData(1, "seq", cmb_EduCrsNm.getValue());
    dts_FileList.setCellData(1, "disclsEduApctTpCd", $c.cp.valueOfIndex(cmb_EduApctTpCd, "VALUE", cmb_EduApctTpCd.getSelectedIndex()));
};

/**
 * @method
 * @name excelUpload
 * @description excel Upload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelUpload = async function() {
    const file_nm = file.getValue();
    const suffix = file_nm.substring(file_nm.lastIndexOf(".") + 1);
    if (cmb_EduCrsNm.getValue() === '') {
        await $c.win.alert("교육회차를 선택하여 주세요.");
        return;
    }
    if (!(suffix === 'xls' || suffix === 'xlsx')) {
        await $c.win.alert("확장자 'xls','xlsx' 만 가능합니다.");
        return;
    }
    const res = window.confirm("[" + $c.cp.valueOfIndex(cmb_EduCrsNm, "TEXT", cmb_EduCrsNm.getSelectedIndex()) + "]에 엑셀자료를 업로드 하시겠습니까?");
    if (res) {
        LastJob = "저장";
        trs_Save.Action = "/DisclsEduaction.do?method=registerExcelUpload" + "&SCREN_ID=" + 'ULDSTF16514.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pFile=dts_FileList)";
        trs_Save.post();
    }
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {void}
 * @hidden N
 */
scwin.save = function() {
    if (window.confirm("저장하겠습니까?")) {
        let url = "/DisclsEduaction.do?method=saveDisclsEduCost" + "&SCREN_ID=" + 'ULDSTF16514.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_gridSave.Action = url;
        trs_gridSave.KeyName = "toinb_dataid4";
        trs_gridSave.KeyValue = "JSP(I:pInput=dts_Grid)";
        trs_gridSave.Post();
    }
};

/**
 * @method
 * @name checkNum
 * @description check Num 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkNum = async function(row, colid, data) {
    let num = dts_Grid.getCellData(row, colid);
    num = num.replace(/\,|\(|\)/g, '');
    num = num.replace(/\s/g, '');
    dts_Grid.setCellData(row, colid, num);
    if (isNaN(dts_Grid.getCellData(row, colid))) {
        await $c.win.alert("올바른 숫자형식으로 값을 입력해주세요.");
        grd_Grid.focus();
    }
};

/**
 * @method
 * @name checkDate
 * @description check Date 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkDate = async function(row, colid, data) {
    let num = dts_Grid.getCellData(row, colid);
    num = num.replace(/\.|\(|\)/g, '');
    num = num.replace(/\s/g, '');
    dts_Grid.setCellData(row, colid, num);
    if (num.length !== 8 && num.length !== 0) {
        await $c.win.alert("올바른 날자를 입력해주세요.");
        grd_Grid.focus();
    }
};

/**
 * @method
 * @name allUpdate
 * @description all Update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.allUpdate = async function() {
    const val = $c.cp.valueOfIndex(cmb_update, "VALUE", cmb_update.getSelectedIndex());
    let column = '';
    const columnValue = '';
    if (val === '1') {
        column = 'PAY_PROCS_STAT_CD';
        getCellData = 'Y';
    } else if (val === '2') {
        column = 'PAY_PROCS_STAT_CD';
        getCellData = 'N';
    } else if (val === '3') {
        column = 'PAY_PROCS_STAT_CD';
        getCellData = 'D';
    } else if (val === '4') {
        column = 'DISCLS_EDU_ATTEND_YN';
        getCellData = 'Y';
    } else if (val === '5') {
        column = 'DISCLS_EDU_ATTEND_YN';
        getCellData = 'N';
    }
    if (val !== '') {
        if (dts_Grid.getRowCount() === 0) {
            await $c.win.alert("업데이트 대상이  없습니다.");
            cmb_update.setValue('');
            return;
        }
        const gCnt = 0;
        let gStat;
        grd_Grid.Redraw = false;
        dts_Grid.setBroadcast(false);
        for (let k = 1; k <= dts_Grid.getRowCount(); k++) {
            // gStat = dts_Grid.RowStatus(k);
            dts_Grid.setCellData(k, column, getCellData);
        }
        dts_Grid.setBroadcast(true, true);
        grd_Grid.Redraw = true;
    }
};

/**
 * @method
 * @name grd_Grid_CanColumnPosChange
 * @description grd Grid Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    value.setValue(dts_Grid.getCellData(row, colid));
    if (isNaN(value) && (colid === 'DISCLS_EDU_APPL_AMT' || colid === 'DISCLS_EDU_COST_DEPO_DD')) {
        return false;
    } else if (colid === 'DISCLS_EDU_COST_DEPO_DD' && !(value.length === 0 || value.length === 8)) {
        return false;
    } else {
        return true;
    }
};
